29			t.Fatalf("get item %s: %v", id, err)
30		}
31		return it
32	}
33	
34	// TestItemJourneyMutationKeepsStoredFacts：调用方改动结果中的事项最新信息
35	// （内容、负责人、归属与流经班次、关闭信息、历史事件）、处理经过（退回原因、
36	// 补充说明与补充时间）和各次交接当前结果（结果、处理人、处理时间、退回轮次）
37	// 后，再次查询仍得到系统原来保存的事实；先取得的另一份结果也保持原样。
38	func TestItemJourneyMutationKeepsStoredFacts(t *testing.T) {
39		f := newFixture(t)
40		_, _, items, h := prepareReportScenario(t, f)
41		idA, idB := items[0].ID, items[1].ID
42	
43		first, err := f.svc.ItemJourney(idB)
44		if err != nil {
45			t.Fatalf("journey: %v", err)
46		}
47		second, err := f.svc.ItemJourney(idB)
48		if err != nil {
49			t.Fatalf("journey again: %v", err)
50		}
51		// 取值当时的 JSON 快照：之后改动结果即使经由共享内存写进存储，
52		// 快照里仍是原值，能识别出任何方向的串改。
53		firstSnapshot := mustJSON(t, first)
54		storedHandover := mustJSON(t, mustGetHandover(t, f, h.ID))
55		storedItem := mustJSON(t, mustItem(t, f, idB))
56		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
57	
58		// 事项最新信息：内容、负责人、归属与流经班次、关闭信息、历史事件。
59		second.Item.Content = "篡改内容"
60		second.Item.FollowOwner = "篡改负责人"
61		second.Item.CurrentShiftID = "S999"
62		second.Item.ShiftIDs = append(second.Item.ShiftIDs, "S999")
63		second.Item.Closed = true
64		second.Item.ClosedAt = &forge
65		second.Item.CloseOperator = "篡改人"
66		second.Item.Events = append(second.Item.Events, ItemEvent{At: forge, Kind: "closed", Operator: "篡改人"})
67	
68		// 处理经过：退回原因、补充说明、补充时间与重新提交时间。
69		ret := findJourneyEvent(second, "return")
70		if ret == nil {
71			t.Fatalf("前置：处理经过应包含退回记录")
72		}
73		ret.Reason = "篡改退回原因"
74		res := findJourneyEvent(second, "resubmit")
75		if res == nil || res.SupplementAt == nil {
76			t.Fatalf("前置：处理经过应包含带补充时间的重新提交记录")
77		}
78		res.Supplement = "篡改补充说明"
79		*res.SupplementAt = forge
80	
81		// 交接当前结果：结果、处理人、处理时间与退回轮次。
82		if len(second.Results) != 1 {
83			t.Fatalf("前置：%s 应恰有一次交接当前结果，got %d", idB, len(second.Results))
84		}
85		entry := &second.Results[0].Entry
86		entry.Status = EntryConfirmed
87		entry.Operator = "篡改人"
88		entry.ProcessedAt = &forge
89		entry.Rounds[0].Reason = "篡改结果里的原因"
90		entry.Rounds[0].Supplement = "篡改结果里的补充"
91		*entry.Rounds[0].SupplementAt = forge
92		*entry.Rounds[0].ResubmittedAt = forge
93	
94		// 已确认事项的处理时间指针同样与存储脱离。
95		ja, err := f.svc.ItemJourney(idA)
96		if err != nil {
97			t.Fatalf("journey %s: %v", idA, err)
98		}
99		ea := &ja.Results[0].Entry
100		if ea.ProcessedAt == nil {
101			t.Fatalf("前置：%s 应已确认并记录处理时间", idA)
102		}
103		*ea.ProcessedAt = forge
104	
105		// 再次查询仍应得到系统原来保存的事实，且与先取得的那份结果完全一致。
106		third, err := f.svc.ItemJourney(idB)
107		if err != nil {
108			t.Fatalf("journey after mutation: %v", err)
109		}
110		if got := mustJSON(t, third); got != firstSnapshot {
111			t.Fatalf("改动结果后再次查询仍应得到系统原来保存的事实\nwant %s\ngot  %s", firstSnapshot, got)
112		}
113		// 系统保存的交接记录与事项记录整体保持原值。
114		if got := mustJSON(t, mustGetHandover(t, f, h.ID)); got != storedHandover {
115			t.Fatalf("系统保存的交接记录不应被查询结果改动\nwant %s\ngot  %s", storedHandover, got)
116		}
117		if got := mustJSON(t, mustItem(t, f, idB)); got != storedItem {
118			t.Fatalf("系统保存的事项记录不应被查询结果改动\nwant %s\ngot  %s", storedItem, got)
119		}
120		stored := mustGetHandover(t, f, h.ID)
121		se := findEntryOf(t, stored, idB)
122		if se.Rounds[0].Reason != "需要补充细节" || se.Rounds[0].Supplement != "补充说明如下" {
123			t.Fatalf("系统保存的退回与补充记录不应被查询结果改动：%+v", se.Rounds[0])
124		}
125	}
126	
127	// TestJourneyEventsAndResultsDoNotShareStorage：同一份结果里，处理经过与交接
128	// 当前结果可能展示同一次补充；两者各是一份副本，仅调整其中一处的补充时间，
129	// 另一处保留原值。
130	func TestJourneyEventsAndResultsDoNotShareStorage(t *testing.T) {
131		f := newFixture(t)
132		_, _, items, _ := prepareReportScenario(t, f)
133		idB := items[1].ID
134		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
135		forge2 := time.Date(2032, 6, 7, 8, 9, 10, 0, time.UTC)
136	
137		j, err := f.svc.ItemJourney(idB)
138		if err != nil {
139			t.Fatalf("journey: %v", err)
140		}
141		res := findJourneyEvent(j, "resubmit")
142		if res == nil || res.SupplementAt == nil {
143			t.Fatalf("前置：处理经过应包含带补充时间的重新提交记录")
144		}
145		round := &j.Results[0].Entry.Rounds[0]
146		if round.SupplementAt == nil || round.ResubmittedAt == nil {
147			t.Fatalf("前置：当前结果的退回轮次应记录补充时间与重新提交时间")
148		}
149		origEvent, origResult := *res.SupplementAt, *round.SupplementAt
150		if !origEvent.Equal(origResult) {
151			t.Fatalf("前置：两处展示同一次补充，时间应一致：%v vs %v", origEvent, origResult)
152		}
153	
154		// 改当前结果里的补充时间，处理经过中的同一补充保留原值。
155		*round.SupplementAt = forge
156		if !res.SupplementAt.Equal(origEvent) {
157			t.Fatalf("改动当前结果的补充时间不应连带改掉处理经过：%v", res.SupplementAt)
158		}
159		// 反向：改处理经过里的补充时间与重新提交时间，当前结果保留刚改的值。
160		*res.SupplementAt = forge2
161		res.At = forge2
162		if !round.SupplementAt.Equal(forge) {
163			t.Fatalf("改动处理经过的补充时间不应连带改掉当前结果：%v", round.SupplementAt)
164		}
165		if !round.ResubmittedAt.Equal(origResult) {
166			t.Fatalf("改动处理经过不应连带改掉当前结果的重新提交时间：%v", round.ResubmittedAt)
167		}
168	}
169	
170	// TestEarlierJourneySurvivesLaterProcessing：事项被退回后先取得处理经过，交班人
171	// 随后在原交接中补充说明并重新提交、接班人再接收，之后事项被修改并关闭：新查询
172	// 反映这些成功操作，先前那份结果仍保留取得时的退回状态、退回原因、未补充情况、
173	// 负责人、所在班次与流经班次，不混入后来的经过。
174	func TestEarlierJourneySurvivesLaterProcessing(t *testing.T) {
175		f := newFixture(t)
176		a, b, items := prepareHandover(t, f)
177		h, err := f.svc.CreateHandover(a.ID, b.ID)
178		if err != nil {
179			t.Fatalf("create handover: %v", err)
180		}
181		idB := items[1].ID
182		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionReturn, "李四", "需要补充细节", "", ""); err != nil {
183			t.Fatalf("return: %v", err)
184		}
185	
186		old, err := f.svc.ItemJourney(idB)
187		if err != nil {
188			t.Fatalf("journey: %v", err)
189		}
190		if old.Results[0].Entry.Status != EntryReturned || len(old.Results[0].Entry.Rounds) != 1 {
191			t.Fatalf("前置：取得时应为退回且只有1轮：%+v", old.Results[0].Entry)
192		}
193	
194		// 交班人补充并重新提交，接班人确认接收，随后修改并关闭事项。
195		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充说明如下"); err != nil {
196			t.Fatalf("resubmit: %v", err)
197		}
198		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
199			t.Fatalf("confirm: %v", err)
200		}
201		if _, err := f.svc.UpdateItem(idB, "接班后修改的内容", SeverityUrgent, "新限制", "新负责人"); err != nil {
202			t.Fatalf("update: %v", err)
203		}
204		if _, err := f.svc.CloseItem(idB, "李四"); err != nil {
205			t.Fatalf("close item: %v", err)
206		}
207	
208		// 新查询反映这些成功操作。
209		fresh, err := f.svc.ItemJourney(idB)
210		if err != nil {
211			t.Fatalf("journey after processing: %v", err)
212		}
213		if fresh.Results[0].Entry.Status != EntryConfirmed || !fresh.Item.Closed ||
214			fresh.Item.FollowOwner != "新负责人" || findJourneyEvent(fresh, "resubmit") == nil {
215			t.Fatalf("新查询应反映补充、接收、修改与关闭：%+v", fresh.Results[0].Entry)
216		}
217	
218		// 先前那份结果仍保留取得时的退回状态、退回原因与未补充情况。
219		oe := old.Results[0].Entry
220		if oe.Status != EntryReturned || oe.Operator != "李四" || oe.ProcessedAt == nil {
221			t.Fatalf("旧结果应保留取得时的退回状态与处理人：%+v", oe)
222		}
223		if oe.Rounds[0].Reason != "需要补充细节" || oe.Rounds[0].Supplement != "" ||
224			oe.Rounds[0].SupplementAt != nil || oe.Rounds[0].ResubmittedAt != nil {
225			t.Fatalf("旧结果应保留取得时的退回原因与未补充情况：%+v", oe.Rounds[0])
226		}
227		// 旧结果中的事项最新信息保持取得时的内容：未关闭、负责人与所在班次不变。
228		if old.Item.Closed || old.Item.ClosedAt != nil || old.Item.FollowOwner != "李四" ||
229			old.Item.CurrentShiftID != a.ID || len(old.Item.ShiftIDs) != 1 {
230			t.Fatalf("旧结果应保留取得时的事项归属、负责人与关闭情况：%+v", old.Item)
231		}
232		// 后来的补充、接收、修改与关闭经过不混入旧结果。
233		for _, kind := range []string{"resubmit", "confirm", "received", "closed"} {
234			if ev := findJourneyEvent(old, kind); ev != nil {
235				t.Fatalf("旧结果不应混入后来的 %s 经过：%+v", kind, ev)
236			}
237		}
238		if ev := findJourneyEvent(old, "updated"); ev != nil {
239			t.Fatalf("旧结果不应混入后来的修改经过：%+v", ev)
240		}
241	}
242	
243	// TestJourneyWithoutHandoverAlsoIndependent：未参与交接的事项仍显示暂无交接
244	// 记录；改动其结果中的事项信息不影响再次查询，也不为独立性补造交接记录。
245	func TestJourneyWithoutHandoverAlsoIndependent(t *testing.T) {
246		f := newFixture(t)
247		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
248		it, err := f.svc.AddItem(a.ID, "未交接事项", SeverityNormal, "", "李四")
249		if err != nil {
250			t.Fatalf("add item: %v", err)
251		}
252		j, err := f.svc.ItemJourney(it.ID)
253		if err != nil {
254			t.Fatalf("journey: %v", err)
255		}
256		if j.HasHandovers || len(j.Results) != 0 {
257			t.Fatalf("未参与交接应显示暂无交接记录：%+v", j.Results)
258		}
259		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
260		j.Item.Content = "篡改内容"
261		j.Item.Events = append(j.Item.Events, ItemEvent{At: forge, Kind: "closed", Operator: "篡改人"})
262		j.Item.ShiftIDs = append(j.Item.ShiftIDs, "S999")
263		again, err := f.svc.ItemJourney(it.ID)
264		if err != nil {
265			t.Fatalf("journey again: %v", err)
266		}
267		if again.HasHandovers || again.Item.Content != "未交接事项" ||
268			len(again.Item.Events) != 1 || len(again.Item.ShiftIDs) != 1 {
269			t.Fatalf("改动结果不应影响再次查询：%+v", again.Item)
270		}
271	}
